class Solution {
public:
    bool xorGame(vector<int>& nums) {
        int x = 0;
        for (int v : nums) x ^= v;
        return x == 0 || nums.size() % 2 == 0;
    }
};

class Solution {
    public boolean xorGame(int[] nums) {
        int x = 0;
        for (int v : nums) x ^= v;
        return x == 0 || nums.length % 2 == 0;
    }
}

var xorGame = function(nums) {
    let x = 0;
    for (const v of nums) x ^= v;
    return x === 0 || nums.length % 2 === 0;
};
